I've fixed this issue by creating (and enabling in the config) `~/.claude-code-router/transformers/fix-glm52.js`:
```js
module.exports = function () {
    return {
        name: 'fix-glm52',
        transformRequestIn(req) {
            if (req.messages && Array.isArray(req.messages)) {
                const model = req.model || '';
                if (model.includes('glm-5.2')) {
                    if (req.reasoning !== undefined) {
                        delete req.reasoning;
                    }
                    if (req.reasoning_effort !== undefined) {
                        delete req.reasoning_effort;
                    }
                    req.messages = req.messages.map((msg) => {
                        if (msg.content && Array.isArray(msg.content)) {
                            const textParts = msg.content
                                .filter((part) => part.type === 'text')
                                .map((part) => part.text);
                            const newContent = textParts.join('\n');
                            msg.content = newContent;
                        }
                        return msg;
                    });
                }
            }
            return req;
        },
    };
};
```

